import { Heading, Text } from '@absoluteui/components/typography';

const section = document.createElement('section');
section.append(
  Heading.create(2, 'Billing', { size: 4 }),
  Text.create('Invoices are issued on the first of each month.', { tone: 'muted', size: 'sm' }),
);
document.body.append(section);

import { Link } from '@absoluteui/components/typography';

const p = document.createElement('p');
p.append('Read the ', Link.create({ href: 'https://example.com/guide', text: 'setup guide', external: true }), '.');
document.body.append(p);

import { setLineClamp } from '@absoluteui/components/typography';

const preview = document.createElement('p');
preview.className = 'aui-text';
preview.textContent = 'A long description that should show at most two lines in the list view.';
document.body.append(preview);
const unclamp = setLineClamp(preview, 2);
preview.addEventListener('click', unclamp, { once: true });

import { configureAbsoluteUI, registerMessages } from '@absoluteui/core';

registerMessages('typography', 'de', { opensInNewTab: '(öffnet in einem neuen Tab)' });
configureAbsoluteUI({ components: { typography: { locale: 'de-DE' } } });
